import { and, eq } from \"drizzle-orm\";
import { getDb, issueDependencies } from \"@/server/db\";
import { toIsoTimestamp } from \"@/types/common\";
import { orgPredicate } from \"./base-repository\";
import type { IssueId, OrgId, UserId } from \"@/types/common\";
import type { IssueDependency } from \"@/types/issue\";

export async function listDependencies(orgId: OrgId): Promise<readonly IssueDependency[]> {
  return getDb().select().from(issueDependencies)
    .where(orgPredicate(issueDependencies.orgId, orgId)).all() as IssueDependency[];
}

export async function insertDependency(orgId: OrgId, issueId: IssueId, blockerId: IssueId, createdBy: UserId): Promise<IssueDependency> {
  getDb().insert(issueDependencies).values({ orgId, issueId, blockerId, createdBy, createdAt: toIsoTimestamp(new Date()) })
    .onConflictDoNothing().run();
  return getDb().select().from(issueDependencies).where(and(
    orgPredicate(issueDependencies.orgId, orgId), eq(issueDependencies.issueId, issueId), eq(issueDependencies.blockerId, blockerId),
  )).get() as IssueDependency;
}

export async function deleteDependency(orgId: OrgId, issueId: IssueId, blockerId: IssueId): Promise<boolean> {
  return getDb().delete(issueDependencies).where(and(
    orgPredicate(issueDependencies.orgId, orgId), eq(issueDependencies.issueId, issueId), eq(issueDependencies.blockerId, blockerId),
  )).run().changes > 0;
}
