  assertNotArchived(\"Issue\", issue.id, issue);
  assertNotArchived(\"Issue\", blocker.id, blocker);
  if (issue.id === blocker.id) throw new Error(\"An issue cannot block itself\");
  const links = await repo.listDependencies(input.orgId);
  const existing = links.find((link) => link.issueId === issue.id && link.blockerId === blocker.id);
  if (existing) return existing;
  const pending: IssueId[] = [blocker.id];
  const visited = new Set<IssueId>();
  while (pending.length) {
    const id = pending.pop()"'!;
    if (id === issue.id) throw new Error("Issue dependency cycle");
    if (visited.has(id)) continue;
    visited.add(id);
    for (const link of links) if (link.issueId === id) pending.push(link.blockerId);
  }
  return repo.insertDependency(input.orgId, issue.id, blocker.id, actor.userId);
}

export async function removeBlocker(actor: Actor, input: Input): Promise<boolean> {
  assertOrgScope(actor, input.orgId);
  const issue = requireFound(await issueRepo.findIssueById(input.orgId, input.issueId), "Issue", input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  return repo.deleteDependency(input.orgId, input.issueId, input.blockerId);
}

export async function listBlockers(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return blockersFor(orgId, issueId);
}

export async function blockersFor(orgId: OrgId, issueId: IssueId): Promise<Issue[]> {
  const links = (await repo.listDependencies(orgId)).filter((link) => link.issueId === issueId);
  const issues = await Promise.all(links.map((link) => issueRepo.findIssueById(orgId, link.blockerId)));
  return issues.filter((issue): issue is Issue => issue !== null && issue.archivedAt === null)
    .sort((a, b) => a.number - b.number);
}

export function isOpen(issue: Issue): boolean {
  return issue.archivedAt === null && issue.status !== "done" && issue.status !== "canceled";
}
