async function notifyUnblocked(orgId: OrgId, blockerId: IssueId, actorId: UserId | null): Promise<void> {
  const links = (await dependencyRepo.listDependencies(orgId)).filter((link) => link.blockerId === blockerId);
  for (const link of links) {
    const issue = await issueRepo.findIssueById(orgId, link.issueId);
    if ("'!issue || !isOpen(issue) || !issue.assigneeId) continue;
    if ((await blockersFor(orgId, issue.id)).some(isOpen)) continue;
    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "Issue unblocked", body: `Issue ${issue.id} is no longer blocked`,
      href: `/issues/${issue.id}`, actorId,
    });
  }
}

export function registerDependencyListeners(): Unsubscribe {
  const offStatus = subscribe("issue.status_changed", async (event) => {
    if (event.from !== "done" && event.from !== "canceled" && (event.to === "done" || event.to === "canceled")) {
      await notifyUnblocked(event.orgId, event.issueId, event.actorId);
    }
  });
  const offArchive = subscribe("issue.archived", async (event) => {
    const issue = await issueRepo.findIssueById(event.orgId, event.issueId);
    if (issue && issue.status !== "done" && issue.status !== "canceled") {
      await notifyUnblocked(event.orgId, event.issueId, event.actorId);
    }
  });
  return () => { offStatus(); offArchive(); };
}
